```python
def check_venmo_account(email):
    page_index = 0
    while True:
        results = apis.venmo.search_users(access_token=venmo_token, query=email, page_index=page_index, page_limit=20)
        if not results:
            break
        for user in results:
            if user["email"] == email:
                return True
        if len(results) < 20:
            break
        page_index += 1
    return False

